def get_user(db, username):
    query = f"SELECT * FROM users WHERE name = '{username}'"
    cur = db.cursor()
    cur.execute(query)
    return cur.fetchone()

def save_pw(username, pw):
    open('/tmp/pws.txt', 'a').write(username + ':' + pw + '\n')
